<?php
session_start(); if(!isset($_SESSION['user_id'])){ header('Location: login.php'); exit; }
$id=intval($_GET['id']??0); $data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true);
if($_SERVER['REQUEST_METHOD']=='POST' && ($_SESSION['role']??'')=='admin'){
 foreach($data['complaints'] as &$c){ if($c['id']==$id){ $c['status']=$_POST['new_status']; $c['admin_response']=$_POST['history_comment']; if(!isset($c['history'])) $c['history']=[]; $c['history'][]=['status'=>$_POST['new_status'],'comment'=>$_POST['history_comment'],'at'=>date('Y-m-d H:i:s')]; break; } }
 file_put_contents(__DIR__.'/fake_db.json',json_encode($data,JSON_PRETTY_PRINT)); header('Location: complaint_details.php?id='.$id.'&saved=1'); exit;
}
$c=null; foreach($data['complaints'] as $x){ if($x['id']==$id){ $c=$x; break; } } if(!$c){ header('Location: admin_dashboard.php'); exit; }
?>
