c['status']; ?></span> <span style="padding:3px 9px;border-radius:10px;font-size:11px;background:#eef2ff"><?php echo $c['category']; ?></span></div><div style="margin-top:10px;font-weight:700"><?php echo htmlspecialchars($c['subject']); ?></div><div style="font-size:11px;color:#6b7280;margin-top:6px"><?php echo htmlspecialchars($c['location']); ?> · <?php echo $c['created_at']; ?></div><div style="margin-top:12px;background:#f9fafb;padding:10px;border-radius:8px;font-size:12px"><?php echo nl2br(htmlspecialchars($c['description'])); ?></div></div><?php if(($_SESSION['role']??'')=='admin'){ ?><div class="card"><div style="font-weight:700;margin-bottom:10px">🔧 Update status & response</div><form method="POST"><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div><label style="font-size:11px;font-weight:600">New status</label><select name="new_status"><option <?php if($c['status']=='Pending') echo 'selected'; ?>>Pending</option><option>In Progress</option><option>Resolved</option><option>Closed</option></select></div><div><label style="font-size:11px;font-weight:600">History comment</label><input name="history_comment" placeholder="e.g. Technician assigned"></div></div><div style="margin-top:10px"><button class="btn" type="submit">💾 Save changes</button></div></form></div><?php } ?></div></div><?php if(isset($_GET['saved'])) echo '<div style="position:fixed;bottom:16px;right:16px;background:#111827;color:#fff;padding:10px 14px;border-radius:12px;font-size:12px">✅ Updated!</div>'; ?></body></html>
